using System;
using System.IO;
using System.Security.Principal;
using System.Diagnostics;
using System.Threading;
using Microsoft.Win32;
using System.Windows.Forms;

[assembly: System.Reflection.AssemblyTitle("FocusLens All-In-One Installer")]
[assembly: System.Reflection.AssemblyDescription("Packaged & Customized by Saiful Islam - saifulislam.net")]
[assembly: System.Reflection.AssemblyCompany("Saiful Islam (saifulislam.net)")]
[assembly: System.Reflection.AssemblyProduct("FocusLens for OBS Studio")]
[assembly: System.Reflection.AssemblyCopyright("Copyright (c) Saiful Islam - saifulislam.net")]
[assembly: System.Reflection.AssemblyVersion("2.2.0.0")]

namespace FocusLensInstaller {
    class Program {
        static bool IsAdministrator() {
            var identity = WindowsIdentity.GetCurrent();
            var principal = new WindowsPrincipal(identity);
            return principal.IsInRole(WindowsBuiltInRole.Administrator);
        }

        static void Main(string[] args) {
            Console.Title = "FocusLens for OBS Studio - Installer (By Saiful Islam)";
            Console.WriteLine("==================================================");
            Console.WriteLine("    FocusLens - Smart Zoom & Focus for OBS Studio ");
            Console.WriteLine("        Packaged & Built by Saiful Islam          ");
            Console.WriteLine("            Website: saifulislam.net              ");
            Console.WriteLine("==================================================");
            


            string obsPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), @"obs-studio\plugins\FocusLens");
            
            Console.WriteLine("\nTarget OBS Directory: " + obsPath);

            Console.WriteLine("\n[1/4] Closing any active background processes...");
            try {
                foreach (var name in new string[] { "FocusLensOSD", "ZoomOSD" }) {
                    foreach (var p in Process.GetProcessesByName(name)) {
                        try {
                            p.Kill();
                            p.WaitForExit(3000);
                        } catch { }
                    }
                }
            } catch { }
            Thread.Sleep(800);

            Console.WriteLine("\n[2/4] Installing FocusLens Plugin core & locale files...");

            try {                WriteFile(obsPath, @"data\\locale\\de-DE.ini", "");                WriteFile(obsPath, @"data\\locale\\en-US.ini", "");                WriteFile(obsPath, @"data\\locale\\es-ES.ini", "");                WriteFile(obsPath, @"data\\locale\\fr-FR.ini", "");                WriteFile(obsPath, @"data\\locale\\it-IT.ini", "");                WriteFile(obsPath, @"data\\locale\\pt-BR.ini", "");                WriteFile(obsPath, @"data\\locale\\pt-PT.ini", "");                WriteFile(obsPath, @"data\\locale\\zh-CN.ini", "");                WriteFile(obsPath, @"bin\\64bit\\FocusLens.dll", "");
                Console.WriteLine("\n[3/4] Installing FocusLens Alert System (FocusLensOSD)...");
                string osdDest = Path.Combine(obsPath, @"obs-plugins\64bit\FocusLensOSD.exe");
                
                int retries = 5;
                while (retries > 0) {
                    try {
                        File.WriteAllBytes(osdDest, Convert.FromBase64String(""));
                        Console.WriteLine("Wrote: obs-plugins\\64bit\\FocusLensOSD.exe");
                        break;
                    } catch (Exception) {
                        retries--;
                        if (retries == 0) throw;
                        foreach (var p in Process.GetProcessesByName("FocusLensOSD")) {
                            try { p.Kill(); p.WaitForExit(2000); } catch { }
                        }
                        foreach (var p in Process.GetProcessesByName("ZoomOSD")) {
                            try { p.Kill(); p.WaitForExit(2000); } catch { }
                        }
                        Thread.Sleep(800);
                    }
                }

                // Clean legacy ZoomOSD.exe from disk if present
                try {
                    string oldZoomOsd = Path.Combine(obsPath, @"obs-plugins\64bit\ZoomOSD.exe");
                    if (File.Exists(oldZoomOsd)) {
                        File.Delete(oldZoomOsd);
                    }
                } catch { }

                Console.WriteLine("\n[4/4] Configuring Auto-Start with Windows Startup...");
                try {
                    RegistryKey runKey = Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run", true);
                    if (runKey != null) {
                        try { runKey.DeleteValue("ZoominatorOSD", false); } catch { }
                        runKey.SetValue("FocusLensOSD", "\"" + osdDest + "\"");
                        runKey.Close();
                        Console.WriteLine("Registered FocusLens OSD to Windows Startup.");
                    }
                } catch (Exception regEx) {
                    Console.WriteLine("Note: Could not set auto-start registry: " + regEx.Message);
                }

                try {
                    Process.Start(new ProcessStartInfo(osdDest) { UseShellExecute = true });
                    Console.WriteLine("FocusLens OSD Alert system started (Real-time OBS sync enabled).");
                } catch { }

                Console.WriteLine("\n==================================================");
                Console.WriteLine(" [SUCCESS] FocusLens Plugin & Alert Installed!    ");
                Console.WriteLine("       Packaged & Built by Saiful Islam           ");
                Console.WriteLine("            Website: saifulislam.net              ");
                Console.WriteLine("==================================================");
                Console.WriteLine("1. FocusLens plugin is now installed into OBS Studio.");
                Console.WriteLine("2. Find it in OBS Studio: Tools -> FocusLens...");
                Console.WriteLine("3. REAL-TIME ZOOM SYNC FIXED:");
                Console.WriteLine("   - When OBS is idle: Alert is 100% HIDDEN (No box, no text).");
                Console.WriteLine("   - When you zoom in: Alert shows 'ZOOM ACTIVE' instantly!");
                Console.WriteLine("   - When you zoom out: Alert immediately disappears!");
                Console.WriteLine("4. Right-click the red tray icon for 'Test Alert (5s Preview)'.");
                Console.WriteLine("5. The alert badge is completely hidden from recordings/streams.");


            } catch (Exception ex) {
                Console.WriteLine("\n[ERROR] An error occurred during installation:");
                Console.WriteLine(ex.Message);
                MessageBox.Show("An error occurred during installation:\n\n" + ex.Message, "FocusLens Installer Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                Console.WriteLine("\nPress any key to exit...");
                Console.ReadKey();
            }
            

        }

        static void WriteFile(string basePath, string relativePath, string base64Data) {
            string fullPath = Path.Combine(basePath, relativePath);
            string directory = Path.GetDirectoryName(fullPath);
            
            if (!Directory.Exists(directory)) {
                Directory.CreateDirectory(directory);
            }
            
            Console.WriteLine("Wrote: " + relativePath);
            File.WriteAllBytes(fullPath, Convert.FromBase64String(base64Data));
        }
    }
}

